/* Anthropic Design Language - Loki Mode Website */

/* Import Fonts */
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&family=Lora:ital,wght@0,400;0,500;0,600;1,400&display=swap');

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Design System Colors */
    --color-dark: #18181B;
    --color-light: #FFFFFF;
    --color-mid-gray: #6B7280;
    --color-light-gray: #F3F4F6;
    --color-indigo: #5B4EEA;
    --color-lavender: #A5B4FC;
    --color-mint: #6EE7B7;
    --color-pink: #F4A3C8;

    /* Semantic Colors */
    --bg-primary: var(--color-light);
    --bg-secondary: var(--color-light-gray);
    --bg-card: #ffffff;
    --text-primary: var(--color-dark);
    --text-secondary: #374151;
    --text-muted: var(--color-mid-gray);
    --accent-primary: var(--color-indigo);
    --accent-secondary: var(--color-lavender);
    --accent-tertiary: var(--color-mint);
    --border-color: #E5E7EB;
}

body {
    font-family: 'Lora', Georgia, serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.7;
    font-size: 16px;
}

h1, h2, h3, h4, h5, h6 {
    font-family: 'Poppins', -apple-system, BlinkMacSystemFont, sans-serif;
    font-weight: 600;
    line-height: 1.2;
    color: var(--text-primary);
}

/* Top Header Bar */
.top-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background-color: var(--bg-card);
    border-bottom: 2px solid var(--border-color);
    padding: 0.75rem 1.5rem;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.header-right {
    display: flex;
    align-items: center;
}

.github-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    background: var(--color-dark);
    color: white;
    padding: 0.5rem 1rem;
    border-radius: 0.5rem;
    text-decoration: none;
    font-weight: 500;
    font-family: 'Poppins', sans-serif;
    font-size: 0.875rem;
    transition: all 0.2s ease;
}

.github-btn:hover {
    background: #2d2d2d;
    transform: translateY(-1px);
}

.github-btn svg {
    flex-shrink: 0;
}

/* Announcement Banner */
.announcement-banner {
    background: linear-gradient(135deg, #5B4EEA 0%, #7C3AED 100%);
    color: white;
    text-align: center;
    padding: 0.6rem 1rem;
    font-size: 0.875rem;
}

.announcement-banner a {
    color: white;
    margin-left: 0.5rem;
    text-decoration: underline;
}

/* App Layout - Sidebar + Main */
.app-layout {
    display: flex;
    min-height: calc(100vh - 100px);
}

/* Sidebar Navigation */
.sidebar {
    width: 240px;
    min-width: 240px;
    background-color: var(--bg-card);
    border-right: 1px solid var(--border-color);
    position: sticky;
    top: 100px;
    height: calc(100vh - 100px);
    overflow-y: auto;
    display: flex;
    flex-direction: column;
}

.sidebar-nav {
    flex: 1;
    padding: 1rem 0;
}

/* Nav Section Headers */
.nav-section {
    padding: 1.25rem 1.25rem 0.5rem;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--text-muted);
    font-family: 'Poppins', sans-serif;
}

.nav-brand {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.nav-brand h1 {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--text-primary);
    letter-spacing: -0.02em;
}

.version {
    background: linear-gradient(135deg, var(--color-indigo), #7C3AED);
    color: white;
    padding: 0.35rem 0.85rem;
    border-radius: 1.5rem;
    font-size: 0.8rem;
    font-weight: 600;
    font-family: 'Poppins', sans-serif;
}

.nav-menu {
    list-style: none;
    padding: 0;
    margin: 0;
}

.nav-menu li {
    margin: 0;
}

.nav-link {
    display: block;
    color: var(--text-muted);
    text-decoration: none;
    font-weight: 500;
    font-family: 'Poppins', sans-serif;
    font-size: 0.95rem;
    padding: 0.85rem 1.5rem;
    transition: all 0.2s ease;
    cursor: pointer;
    border-left: 3px solid transparent;
}

.nav-link:hover {
    color: var(--accent-primary);
    background-color: rgba(91, 78, 234, 0.05);
}

.nav-link.active {
    color: var(--accent-primary);
    background-color: rgba(91, 78, 234, 0.1);
    border-left-color: var(--accent-primary);
    font-weight: 600;
}

/* Blog Cards */
.blog-card {
    background-color: var(--bg-card);
    border: 2px solid var(--border-color);
    border-radius: 1rem;
    padding: 1.75rem;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
}

.blog-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(20, 20, 19, 0.08);
    border-color: var(--accent-primary);
}

.blog-date {
    font-size: 0.75rem;
    color: var(--text-muted);
    font-family: 'Poppins', sans-serif;
    margin-bottom: 0.5rem;
}

.blog-card h3 {
    color: var(--text-primary);
    margin-bottom: 0.75rem;
    font-size: 1.15rem;
    font-weight: 600;
}

.blog-card p {
    color: var(--text-secondary);
    font-size: 0.95rem;
    line-height: 1.6;
    margin-bottom: 1rem;
}

.blog-tag {
    display: inline-block;
    background-color: var(--bg-secondary);
    color: var(--text-muted);
    padding: 0.25rem 0.75rem;
    border-radius: 1rem;
    font-size: 0.75rem;
    font-weight: 500;
    font-family: 'Poppins', sans-serif;
}

/* Main Content */
.main-content {
    flex: 1;
    max-width: 1000px;
    margin: 0 auto;
    padding: 2rem 3rem;
    min-width: 0; /* Prevent flex item overflow */
}

.section {
    display: none;
    animation: fadeIn 0.6s ease-in-out;
}

.section.active {
    display: block;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Hero Section */
.hero {
    text-align: center;
    padding: 5rem 2rem 4rem;
}

.hero-title {
    font-size: 5rem;
    font-weight: 800;
    color: var(--text-primary);
    margin-bottom: 1rem;
    letter-spacing: -0.03em;
}

.hero-subtitle {
    font-size: 1.75rem;
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-weight: 500;
    font-family: 'Poppins', sans-serif;
}

.hero-description {
    font-size: 1.2rem;
    color: var(--text-muted);
    max-width: 800px;
    margin: 0 auto 2.5rem;
    line-height: 1.8;
}

.hero-buttons {
    display: flex;
    gap: 1.25rem;
    justify-content: center;
    margin-top: 2rem;
}

.btn {
    padding: 0.95rem 2.5rem;
    border-radius: 3rem;
    text-decoration: none;
    font-weight: 600;
    font-family: 'Poppins', sans-serif;
    font-size: 1rem;
    transition: all 0.3s ease;
    display: inline-block;
}

.btn-primary {
    background: linear-gradient(135deg, var(--color-indigo), #7C3AED);
    color: white;
    border: none;
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(91, 78, 234, 0.35);
}

.btn-secondary {
    background-color: transparent;
    color: var(--accent-primary);
    border: 2px solid var(--accent-primary);
}

.btn-secondary:hover {
    background-color: var(--accent-primary);
    color: white;
    transform: translateY(-3px);
}

/* Features Grid */
.features {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2rem;
    margin: 5rem 0;
}

.feature-card {
    background-color: var(--bg-card);
    border: 2px solid var(--border-color);
    border-radius: 1.5rem;
    padding: 2.5rem;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
}

.feature-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 4px;
    background: linear-gradient(90deg, var(--color-indigo), var(--color-mint), var(--color-lavender));
    opacity: 0;
    transition: opacity 0.3s ease;
}

.feature-card:hover::before {
    opacity: 1;
}

.feature-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 36px rgba(20, 20, 19, 0.08);
    border-color: var(--accent-primary);
}

.feature-card h3 {
    color: var(--accent-primary);
    margin-bottom: 1rem;
    font-size: 1.35rem;
    font-weight: 600;
}

.feature-card p {
    color: var(--text-secondary);
    margin-bottom: 1.25rem;
    line-height: 1.7;
}

.feature-badge {
    display: inline-block;
    background: linear-gradient(135deg, var(--color-indigo), #7C3AED);
    color: white;
    padding: 0.4rem 0.9rem;
    border-radius: 1.5rem;
    font-size: 0.8rem;
    font-weight: 600;
    font-family: 'Poppins', sans-serif;
}

/* Quick Start */
.quick-start {
    background: linear-gradient(135deg, #ffffff, var(--bg-secondary));
    border: 2px solid var(--border-color);
    border-radius: 1.5rem;
    padding: 2.5rem;
    margin: 4rem 0;
}

.quick-start h2 {
    margin-bottom: 1.5rem;
    color: var(--accent-primary);
    font-size: 1.75rem;
}

.quick-start pre {
    background-color: var(--color-dark);
    border-radius: 1rem;
    padding: 2rem;
    overflow-x: auto;
    border: 2px solid #2a2a28;
}

.quick-start code {
    color: var(--color-mint);
    font-family: 'Monaco', 'Courier New', monospace;
    font-size: 0.95rem;
    line-height: 1.6;
}

/* Section Headers */
.section-header {
    text-align: center;
    margin-bottom: 4rem;
}

.section-header h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
    color: var(--text-primary);
    font-weight: 700;
    letter-spacing: -0.02em;
}

.section-header p {
    color: var(--text-muted);
    font-size: 1.25rem;
    font-weight: 400;
}

/* Docs Grid - Enterprise Index Style */
.docs-grid {
    display: flex;
    flex-direction: column;
    gap: 0;
    margin-bottom: 2rem;
    border: 1px solid var(--border-color);
    border-radius: 0.5rem;
    overflow: hidden;
    background: var(--bg-card);
}

.doc-card {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.875rem 1.25rem;
    cursor: pointer;
    transition: background-color 0.15s ease;
    border-bottom: 1px solid var(--border-color);
}

.doc-card:last-child {
    border-bottom: none;
}

.doc-card::after {
    content: '>';
    font-size: 0.875rem;
    color: var(--text-muted);
    font-family: monospace;
    transition: color 0.15s ease;
}

.doc-card:hover {
    background-color: rgba(91, 78, 234, 0.05);
}

.doc-card:hover::after {
    color: var(--accent-primary);
}

.doc-card h3 {
    color: var(--accent-primary);
    margin: 0;
    font-size: 0.9rem;
    font-weight: 600;
    flex-shrink: 0;
}

.doc-card p {
    color: var(--text-muted);
    font-size: 0.8rem;
    margin: 0 0 0 1rem;
    line-height: 1.4;
    flex: 1;
    text-align: right;
}

/* Modal */
.modal {
    display: none;
    position: fixed;
    z-index: 2000;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(20, 20, 19, 0.85);
    overflow-y: auto;
    backdrop-filter: blur(4px);
}

.modal-content {
    background-color: var(--bg-card);
    margin: 3% auto;
    padding: 4rem;
    border: 2px solid var(--border-color);
    border-radius: 2rem;
    width: 90%;
    max-width: 1000px;
    position: relative;
    box-shadow: 0 20px 60px rgba(20, 20, 19, 0.15);
}

.close {
    color: var(--text-muted);
    float: right;
    font-size: 2.5rem;
    font-weight: 300;
    cursor: pointer;
    transition: color 0.3s;
    line-height: 1;
}

.close:hover {
    color: var(--accent-primary);
}

#docContent {
    margin-top: 2rem;
}

#docContent h1,
#docContent h2,
#docContent h3,
#docContent h4 {
    color: var(--text-primary);
    margin: 2.5rem 0 1.25rem 0;
    font-family: 'Poppins', sans-serif;
}

#docContent h1 {
    font-size: 2.75rem;
    border-bottom: 3px solid var(--accent-primary);
    padding-bottom: 0.75rem;
    margin-bottom: 2rem;
}

#docContent h2 {
    font-size: 2rem;
    color: var(--accent-primary);
}

#docContent h3 {
    font-size: 1.5rem;
}

#docContent p {
    margin: 1.25rem 0;
    line-height: 1.8;
    color: var(--text-secondary);
}

#docContent code {
    background-color: var(--bg-secondary);
    padding: 0.3rem 0.6rem;
    border-radius: 0.375rem;
    color: var(--accent-tertiary);
    font-family: 'Monaco', 'Courier New', monospace;
    font-size: 0.9rem;
}

#docContent pre {
    background-color: var(--color-dark);
    border-radius: 1rem;
    padding: 2rem;
    overflow-x: auto;
    margin: 1.5rem 0;
    border: 2px solid #2a2a28;
}

#docContent pre code {
    background-color: transparent;
    padding: 0;
    color: var(--color-mint);
}

#docContent a {
    color: var(--accent-primary);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: border-color 0.3s;
}

#docContent a:hover {
    border-bottom-color: var(--accent-primary);
}

#docContent table {
    width: 100%;
    border-collapse: collapse;
    margin: 2rem 0;
    background-color: var(--bg-card);
}

#docContent th,
#docContent td {
    border: 2px solid var(--border-color);
    padding: 1rem 1.25rem;
    text-align: left;
}

#docContent th {
    background-color: var(--bg-secondary);
    color: var(--text-primary);
    font-weight: 600;
    font-family: 'Poppins', sans-serif;
}

#docContent td {
    color: var(--text-secondary);
}

#docContent blockquote {
    border-left: 4px solid var(--accent-primary);
    margin: 2rem 0;
    color: var(--text-secondary);
    font-style: italic;
    background-color: var(--bg-secondary);
    padding: 1.5rem;
    padding-left: 1.5rem;
    border-radius: 0.5rem;
}

#docContent ul,
#docContent ol {
    margin: 1.25rem 0 1.25rem 2.5rem;
    color: var(--text-secondary);
}

#docContent li {
    margin: 0.75rem 0;
    line-height: 1.7;
}

/* Footer */
.footer {
    background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
    border-top: 2px solid var(--border-color);
    margin-top: 6rem;
    padding: 3rem 2rem;
    text-align: center;
}

.footer-content p {
    color: var(--text-muted);
    margin: 0.75rem 0;
    font-size: 0.95rem;
}

.footer-content a {
    color: var(--accent-primary);
    transition: color 0.3s;
}

.footer-content a:hover {
    color: var(--accent-secondary);
}

/* Hamburger Menu - hidden on desktop */
.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    padding: 0.5rem;
}

.hamburger span {
    width: 25px;
    height: 3px;
    background-color: var(--text-primary);
    margin: 3px 0;
    border-radius: 2px;
    transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
    opacity: 0;
}

.hamburger.active span:nth-child(3) {
    transform: rotate(-45deg) translate(7px, -6px);
}

/* Responsive - Tablet */
@media (max-width: 1024px) {
    .sidebar {
        width: 220px;
        min-width: 220px;
    }

    .main-content {
        padding: 2rem;
    }

    .features {
        grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    }

    .docs-grid {
        grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    }
}

/* Responsive - Mobile */
@media (max-width: 768px) {
    /* Top header adjustments */
    .top-header {
        padding: 0.6rem 1rem;
    }

    .github-text {
        display: none;
    }

    .github-btn {
        padding: 0.5rem;
    }

    /* Sidebar becomes off-canvas */
    .sidebar {
        position: fixed;
        left: -260px;
        top: 0;
        height: 100vh;
        z-index: 999;
        transition: left 0.3s ease;
        box-shadow: none;
    }

    .sidebar.active {
        left: 0;
        box-shadow: 4px 0 20px rgba(0,0,0,0.15);
    }

    .app-layout {
        flex-direction: column;
    }

    /* Show hamburger on mobile */
    .hamburger {
        display: flex;
    }

    .nav-brand h1 {
        font-size: 1.15rem;
    }

    .version {
        font-size: 0.7rem;
        padding: 0.25rem 0.5rem;
    }

    /* Overlay when sidebar is open */
    .sidebar-overlay {
        display: none;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0,0,0,0.5);
        z-index: 998;
    }

    .sidebar-overlay.active {
        display: block;
    }

    /* Announcement banner */
    .announcement-banner {
        font-size: 0.8rem;
        padding: 0.5rem 1rem;
    }

    /* Main Content */
    .main-content {
        padding: 1.5rem 1rem;
    }

    /* Hero */
    .hero {
        padding: 2rem 0.5rem;
    }

    .hero-title {
        font-size: 2.25rem;
    }

    .hero-subtitle {
        font-size: 1.1rem;
    }

    .hero-description {
        font-size: 1rem;
        padding: 0 0.5rem;
    }

    .hero-buttons {
        flex-direction: column;
        gap: 1rem;
        padding: 0 1rem;
    }

    .btn {
        width: 100%;
        text-align: center;
        padding: 0.85rem 1.5rem;
    }

    /* Features */
    .features {
        grid-template-columns: 1fr;
        gap: 1rem;
        margin: 2rem 0;
    }

    .feature-card {
        padding: 1.5rem;
        border-radius: 1rem;
    }

    .feature-card h3 {
        font-size: 1.15rem;
    }

    /* Quick Start */
    .quick-start {
        padding: 1.5rem 1rem;
        margin: 2rem 0;
        border-radius: 1rem;
    }

    .quick-start h2 {
        font-size: 1.35rem;
    }

    .quick-start pre {
        padding: 1rem;
        border-radius: 0.75rem;
    }

    .quick-start code {
        font-size: 0.8rem;
        white-space: pre-wrap;
        word-wrap: break-word;
    }

    /* Section Headers */
    .section-header {
        margin-bottom: 2rem;
    }

    .section-header h2 {
        font-size: 1.75rem;
    }

    .section-header p {
        font-size: 1rem;
        padding: 0 0.5rem;
    }

    /* Docs Grid - Mobile */
    .docs-grid {
        border-radius: 0.375rem;
    }

    .doc-card {
        flex-direction: column;
        align-items: flex-start;
        padding: 0.75rem 1rem;
        gap: 0.25rem;
    }

    .doc-card h3 {
        font-size: 0.85rem;
    }

    .doc-card p {
        text-align: left;
        margin: 0;
        font-size: 0.75rem;
    }

    .doc-card::after {
        display: none;
    }

    /* Modal - Full screen on mobile */
    .modal-content {
        width: 100%;
        max-width: 100%;
        margin: 0;
        padding: 1.5rem 1rem;
        border-radius: 0;
        min-height: 100vh;
        border: none;
    }

    .close {
        font-size: 2rem;
        position: sticky;
        top: 0;
        background: var(--bg-card);
        padding: 0.5rem;
        z-index: 10;
    }

    #docContent {
        margin-top: 1rem;
    }

    #docContent h1 {
        font-size: 1.5rem;
        word-wrap: break-word;
    }

    #docContent h2 {
        font-size: 1.35rem;
        word-wrap: break-word;
    }

    #docContent h3 {
        font-size: 1.15rem;
    }

    #docContent p {
        font-size: 0.95rem;
        line-height: 1.7;
    }

    #docContent pre {
        padding: 1rem;
        border-radius: 0.75rem;
        margin: 1rem -1rem;
        width: calc(100% + 2rem);
    }

    #docContent pre code {
        font-size: 0.75rem;
        white-space: pre-wrap;
        word-wrap: break-word;
        word-break: break-all;
    }

    #docContent code {
        font-size: 0.8rem;
        word-wrap: break-word;
        word-break: break-all;
    }

    #docContent ul,
    #docContent ol {
        margin-left: 1.5rem;
    }

    /* Tables - Scrollable on mobile */
    #docContent table {
        display: block;
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
        margin: 1rem 0;
        font-size: 0.85rem;
    }

    #docContent th,
    #docContent td {
        padding: 0.75rem;
        min-width: 100px;
    }

    #docContent blockquote {
